// Alert when the newest backup try failed, or when there has been no good backup for 26 hours (the job may not be
// running at all: container stopped, PC off for days). All well: no output, so nothing is posted.
const row = $('Read backup runs').first().json;
const now = new Date(row.checked_at);
const lastGood = row.last_good ? new Date(row.last_good) : null;
const hoursSince = lastGood ? Math.floor((now - lastGood) / 3_600_000) : null;

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const short = (t, max) => {
  const s = String(t ?? '').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
};
const when = (d) => d.toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'medium', timeStyle: 'short' });

let problem = null;
if (row.newest_ok === false) {
  problem = `The last backup try failed (${when(new Date(row.newest_at))} New York):\n\`${esc(short(row.newest_error, 300)).replace(/`/g, "'")}\``;
} else if (hoursSince === null) {
  problem = 'There has never been a good backup.';
} else if (hoursSince >= 26) {
  problem = `No good backup for ${hoursSince} hours. Is the backup service running (and the PC on)?`;
}
if (!problem) return [];

const last = lastGood ? `Last good backup: ${when(lastGood)} New York (${hoursSince} h ago).` : 'No good backup on record.';
return [{ json: { text: `:floppy_disk: *Backup problem*\n${problem}\n${last}\nOn the PC: \`docker compose -f compose.dev.yaml logs backup --tail 20\`` } }];
